package promptarchive

import (
	"context"
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/claude-code-proxy/proxy/internal/diagnostics"
	"github.com/claude-code-proxy/proxy/pkg/models"
	_ "modernc.org/sqlite"
)

const (
	DefaultRetention = 168 * time.Hour
	DefaultMaxPayloadBytes = 5 * 1024 * 1024
	maxDeltaDepth = 20
)

type Options struct { Retention time.Duration; BusyTimeout time.Duration; Now func() time.Time }
type Store struct { db *sql.DB; retention time.Duration; now func() time.Time; jobs chan Record; stop chan struct{}; worker sync.WaitGroup; dropped atomic.Uint64; dbMu sync.Mutex; closing bool; lifecycleMu sync.Mutex; sessionHMACKey []byte }
type Record struct {
	RequestID string `json:"request_id"`; CreatedAt time.Time `json:"created_at"`; Model string `json:"model"`; MessageCount int `json:"message_count"`; ToolCount int `json:"tool_count"`; SystemBytes int `json:"system_bytes"`; RawBytes int `json:"raw_bytes"`; Summary string `json:"summary"`; Truncated bool `json:"truncated"`; Payload json.RawMessage `json:"payload,omitempty"`
	StorageKind string `json:"storage_kind,omitempty"`; Incremental bool `json:"incremental,omitempty"`; StoredBytes int `json:"stored_bytes,omitempty"`; ReconstructedBytes int `json:"reconstructed_bytes,omitempty"`; PayloadState string `json:"payload_state,omitempty"`
	sessionID string
}
type Query struct { RequestID string; Model string; Keyword string; Since time.Time; Until time.Time; Limit int; Offset int }
type Statistics struct { FullCount int `json:"full_count"`; DeltaCount int `json:"delta_count"`; StoredBytes int64 `json:"stored_bytes"`; ReconstructedBytes int64 `json:"reconstructed_bytes"` }

func Open(path string, options Options) (*Store, error) {
	if strings.TrimSpace(path)=="" { return nil, errors.New("prompt archive database path is required") }
	if path!=":memory:" { absolute,err:=filepath.Abs(path); if err!=nil{return nil,fmt.Errorf("resolve prompt archive database path: %w",err)}; path=absolute; if err=os.MkdirAll(filepath.Dir(path),0700);err!=nil{return nil,fmt.Errorf("create prompt archive database directory: %w",err)} }
	db,err:=sql.Open("sqlite",path); if err!=nil{return nil,fmt.Errorf("open prompt archive database: %w",err)}; db.SetMaxOpenConns(1); db.SetMaxIdleConns(1)
	s:=&Store{db:db,retention:options.Retention,now:options.Now}; if s.retention<=0{s.retention=DefaultRetention};if s.now==nil{s.now=time.Now}; busy:=options.BusyTimeout;if busy<=0{busy=5*time.Second}; ctx,cancel:=context.WithTimeout(context.Background(),busy+time.Second);defer cancel()
	if err=s.initialize(ctx,busy,path!=":memory:");err!=nil{db.Close();return nil,err};s.startWriter();return s,nil
}
func (s *Store) initialize(ctx context.Context,busy time.Duration,wal bool) error {
	if err:=s.db.PingContext(ctx);err!=nil{return fmt.Errorf("ping prompt archive database: %w",err)}; if _,err:=s.db.ExecContext(ctx,fmt.Sprintf("PRAGMA busy_timeout = %d",busy.Milliseconds()));err!=nil{return err};if wal{if _,err:=s.db.ExecContext(ctx,"PRAGMA journal_mode = WAL");err!=nil{return err}};if _,err:=s.db.ExecContext(ctx,"PRAGMA foreign_keys = ON");err!=nil{return err}
	_,err:=s.db.ExecContext(ctx,`CREATE TABLE IF NOT EXISTS prompt_archive (request_id TEXT PRIMARY KEY, created_at INTEGER NOT NULL, model TEXT NOT NULL DEFAULT '', message_count INTEGER NOT NULL DEFAULT 0, tool_count INTEGER NOT NULL DEFAULT 0, system_bytes INTEGER NOT NULL DEFAULT 0, raw_bytes INTEGER NOT NULL DEFAULT 0, summary TEXT NOT NULL DEFAULT '', truncated INTEGER NOT NULL DEFAULT 0, payload_hash TEXT NOT NULL DEFAULT '', session_key TEXT NOT NULL DEFAULT '', storage_kind TEXT NOT NULL DEFAULT 'full', base_request_id TEXT NOT NULL DEFAULT '', delta_depth INTEGER NOT NULL DEFAULT 0, stored_bytes INTEGER NOT NULL DEFAULT 0, reconstructed_bytes INTEGER NOT NULL DEFAULT 0, payload_state TEXT NOT NULL DEFAULT 'available'); CREATE TABLE IF NOT EXISTS prompt_archive_payloads (request_id TEXT PRIMARY KEY, created_at INTEGER NOT NULL, payload BLOB NOT NULL, FOREIGN KEY (request_id) REFERENCES prompt_archive(request_id) ON DELETE CASCADE); CREATE TABLE IF NOT EXISTS prompt_archive_metadata (name TEXT PRIMARY KEY, value BLOB NOT NULL); CREATE INDEX IF NOT EXISTS idx_prompt_archive_created_at ON prompt_archive(created_at DESC,request_id DESC);`);if err!=nil{return fmt.Errorf("create prompt archive schema: %w",err)}
	for _,column:=range []string{"session_key TEXT NOT NULL DEFAULT ''","storage_kind TEXT NOT NULL DEFAULT 'full'","base_request_id TEXT NOT NULL DEFAULT ''","delta_depth INTEGER NOT NULL DEFAULT 0","stored_bytes INTEGER NOT NULL DEFAULT 0","reconstructed_bytes INTEGER NOT NULL DEFAULT 0","payload_state TEXT NOT NULL DEFAULT 'available'"}{if _,err:=s.db.ExecContext(ctx,"ALTER TABLE prompt_archive ADD COLUMN "+column);err!=nil&&!strings.Contains(strings.ToLower(err.Error()),"duplicate column name"){return fmt.Errorf("migrate prompt archive column %q: %w",column,err)}}
	if _,err=s.db.ExecContext(ctx,"CREATE INDEX IF NOT EXISTS idx_prompt_archive_session ON prompt_archive(session_key,created_at DESC,request_id DESC)");err!=nil{return err}
	if _,err=s.db.ExecContext(ctx,"UPDATE prompt_archive SET stored_bytes=COALESCE((SELECT length(payload) FROM prompt_archive_payloads p WHERE p.request_id=prompt_archive.request_id),0), reconstructed_bytes=COALESCE((SELECT length(payload) FROM prompt_archive_payloads p WHERE p.request_id=prompt_archive.request_id),0) WHERE stored_bytes=0");err!=nil{return err}
	var key []byte;err=s.db.QueryRowContext(ctx,"SELECT value FROM prompt_archive_metadata WHERE name='session_hmac_key'").Scan(&key);if errors.Is(err,sql.ErrNoRows){key=make([]byte,32);if _,err=rand.Read(key);err!=nil{return err};if _,err=s.db.ExecContext(ctx,"INSERT INTO prompt_archive_metadata(name,value) VALUES('session_hmac_key',?)",key);err!=nil{return err}} else if err!=nil{return err};s.sessionHMACKey=key
	cutoff:=toMillis(s.now().UTC().Add(-s.retention));rows,err:=s.db.QueryContext(ctx,"SELECT request_id FROM prompt_archive WHERE created_at < ?",cutoff);if err!=nil{return err};var expired []string;for rows.Next(){var id string;if err=rows.Scan(&id);err!=nil{rows.Close();return err};expired=append(expired,id)};if err=rows.Err();err!=nil{rows.Close();return err};if err=rows.Close();err!=nil{return err};for _,id:=range expired{if _,err=s.deleteLocked(ctx,id);err!=nil{return err}};return nil
}
func (s *Store) Close() error { if s==nil||s.db==nil{return nil};s.lifecycleMu.Lock();if s.closing{s.lifecycleMu.Unlock();return nil};s.closing=true;close(s.stop);s.lifecycleMu.Unlock();s.worker.Wait();return s.db.Close() }
func (s *Store) startWriter(){s.jobs=make(chan Record,256);s.stop=make(chan struct{});s.worker.Add(1);go func(){defer s.worker.Done();for{select{case r:=<-s.jobs:if err:=s.Insert(context.Background(),r);err!=nil{s.dropped.Add(1);fmt.Printf("[WARN] Prompt archive persistence failed request_id=%s: %v\n",r.RequestID,err)};case <-s.stop:for{select{case r:=<-s.jobs:_=s.Insert(context.Background(),r);default:return}}}}}()}
func (s *Store) Enqueue(r Record) bool {if s==nil{return false};s.lifecycleMu.Lock();defer s.lifecycleMu.Unlock();if s.closing||s.jobs==nil{return false};select{case s.jobs<-r:return true;default:s.dropped.Add(1);return false}}
func (s *Store) sessionKey(id string) string {id=strings.TrimSpace(id);if id==""||len(s.sessionHMACKey)==0{return ""};m:=hmac.New(sha256.New,s.sessionHMACKey);_,_=m.Write([]byte(id));return hex.EncodeToString(m.Sum(nil))}
func (s *Store) Insert(ctx context.Context,r Record) error {
	r.RequestID=strings.TrimSpace(r.RequestID);if r.RequestID==""{return errors.New("prompt archive request ID is required")};if r.CreatedAt.IsZero(){r.CreatedAt=s.now().UTC()};full:=[]byte(r.Payload);if len(full)==0{full=[]byte(`{}`)};hash:=hashPayload(full);key:=s.sessionKey(r.sessionID);kind,base,depth,stored:="full","",0,full
	s.dbMu.Lock();defer s.dbMu.Unlock();tx,err:=s.db.BeginTx(ctx,nil);if err!=nil{return err};ok:=false;defer func(){if !ok{_ = tx.Rollback()}}()
	if err=s.materializeDependentsTx(ctx,tx,r.RequestID);err!=nil{return err}
	if key!=""&&!r.Truncated {var id,previousHash string;var previousDepth int;err=tx.QueryRowContext(ctx,`SELECT request_id,payload_hash,delta_depth FROM prompt_archive WHERE session_key=? AND request_id<>? AND payload_state='available' ORDER BY created_at DESC,request_id DESC LIMIT 1`,key,r.RequestID).Scan(&id,&previousHash,&previousDepth);if err==nil&&previousDepth<maxDeltaDepth {basePayload,decodeErr:=s.reconstructTx(ctx,tx,id);if decodeErr==nil&&hashPayload(basePayload)==previousHash {if delta,deltaErr:=makeByteDelta(basePayload,full);deltaErr==nil&&len(delta)<len(full)*9/10 {kind="delta";base=id;depth=previousDepth+1;stored=delta}}}}
	if _,err=tx.ExecContext(ctx,`INSERT INTO prompt_archive(request_id,created_at,model,message_count,tool_count,system_bytes,raw_bytes,summary,truncated,payload_hash,session_key,storage_kind,base_request_id,delta_depth,stored_bytes,reconstructed_bytes,payload_state) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(request_id) DO UPDATE SET created_at=excluded.created_at,model=excluded.model,message_count=excluded.message_count,tool_count=excluded.tool_count,system_bytes=excluded.system_bytes,raw_bytes=excluded.raw_bytes,summary=excluded.summary,truncated=excluded.truncated,payload_hash=excluded.payload_hash,session_key=excluded.session_key,storage_kind=excluded.storage_kind,base_request_id=excluded.base_request_id,delta_depth=excluded.delta_depth,stored_bytes=excluded.stored_bytes,reconstructed_bytes=excluded.reconstructed_bytes,payload_state=excluded.payload_state`,r.RequestID,toMillis(r.CreatedAt),r.Model,r.MessageCount,r.ToolCount,r.SystemBytes,r.RawBytes,r.Summary,boolInt(r.Truncated),hash,key,kind,base,depth,len(stored),len(full),"available");err!=nil{return err};if _,err=tx.ExecContext(ctx,`INSERT INTO prompt_archive_payloads(request_id,created_at,payload) VALUES(?,?,?) ON CONFLICT(request_id) DO UPDATE SET created_at=excluded.created_at,payload=excluded.payload`,r.RequestID,toMillis(r.CreatedAt),stored);err!=nil{return err};if err=tx.Commit();err!=nil{return err};ok=true;return nil
}
func hashPayload(b []byte)string{v:=sha256.Sum256(b);return hex.EncodeToString(v[:])}
type byteDelta struct { Prefix int `json:"prefix"`; Suffix int `json:"suffix"`; Replace []byte `json:"replace"` }
func makeByteDelta(base,next []byte)([]byte,error){prefix:=0;for prefix<len(base)&&prefix<len(next)&&base[prefix]==next[prefix]{prefix++};suffix:=0;for suffix<len(base)-prefix&&suffix<len(next)-prefix&&base[len(base)-1-suffix]==next[len(next)-1-suffix]{suffix++};return json.Marshal(byteDelta{Prefix:prefix,Suffix:suffix,Replace:next[prefix:len(next)-suffix]})}
func applyByteDelta(base,encoded []byte)([]byte,error){var d byteDelta;if err:=json.Unmarshal(encoded,&d);err!=nil{return nil,err};if d.Prefix<0||d.Suffix<0||d.Prefix+d.Suffix>len(base){return nil,errors.New("invalid prompt archive delta")};out:=make([]byte,0,d.Prefix+len(d.Replace)+d.Suffix);out=append(out,base[:d.Prefix]...);out=append(out,d.Replace...);out=append(out,base[len(base)-d.Suffix:]...);return out,nil}
func (s *Store) reconstructTx(ctx context.Context,tx *sql.Tx,id string)([]byte,error){return s.reconstructTxVisited(ctx,tx,id,map[string]bool{})}
func (s *Store) reconstructTxVisited(ctx context.Context,tx *sql.Tx,id string,visited map[string]bool)([]byte,error){if visited[id]{return nil,errors.New("prompt archive delta cycle detected")};visited[id]=true;defer delete(visited,id);var kind,base,hash string;var payload []byte;err:=tx.QueryRowContext(ctx,`SELECT a.storage_kind,a.base_request_id,a.payload_hash,p.payload FROM prompt_archive a JOIN prompt_archive_payloads p ON p.request_id=a.request_id WHERE a.request_id=?`,id).Scan(&kind,&base,&hash,&payload);if err!=nil{return nil,err};if kind=="delta"{parent,err:=s.reconstructTxVisited(ctx,tx,base,visited);if err!=nil{return nil,err};payload,err=applyByteDelta(parent,payload);if err!=nil{return nil,err}};if hash!=""&&hashPayload(payload)!=hash{return nil,errors.New("prompt archive payload integrity check failed")};return payload,nil}
func (s *Store) Query(ctx context.Context,q Query)([]Record,error){where,args:=buildWhere(q);statement:=`SELECT request_id,created_at,model,message_count,tool_count,system_bytes,raw_bytes,summary,truncated,storage_kind,stored_bytes,reconstructed_bytes,payload_state FROM prompt_archive`+where+` ORDER BY created_at DESC,request_id DESC`;limit:=q.Limit;if limit<=0{limit=50};if limit>200{limit=200};statement+=" LIMIT ?";args=append(args,limit);if q.Offset>0{statement+=" OFFSET ?";args=append(args,q.Offset)};s.dbMu.Lock();defer s.dbMu.Unlock();rows,err:=s.db.QueryContext(ctx,statement,args...);if err!=nil{return nil,err};defer rows.Close();var result []Record;for rows.Next(){var r Record;var ms int64;var tr int;if err=rows.Scan(&r.RequestID,&ms,&r.Model,&r.MessageCount,&r.ToolCount,&r.SystemBytes,&r.RawBytes,&r.Summary,&tr,&r.StorageKind,&r.StoredBytes,&r.ReconstructedBytes,&r.PayloadState);err!=nil{return nil,err};r.CreatedAt=fromMillis(ms);r.Truncated=tr!=0;r.Incremental=r.StorageKind=="delta";result=append(result,r)};return result,rows.Err()}
func (s *Store) Count(ctx context.Context,q Query)(int,error){where,args:=buildWhere(q);var n int;s.dbMu.Lock();defer s.dbMu.Unlock();err:=s.db.QueryRowContext(ctx,"SELECT COUNT(*) FROM prompt_archive"+where,args...).Scan(&n);return n,err}
func (s *Store) Detail(ctx context.Context,id string)(Record,error){s.dbMu.Lock();defer s.dbMu.Unlock();tx,err:=s.db.BeginTx(ctx,nil);if err!=nil{return Record{},err};defer tx.Rollback();var r Record;var ms int64;var tr int;err=tx.QueryRowContext(ctx,`SELECT request_id,created_at,model,message_count,tool_count,system_bytes,raw_bytes,summary,truncated,storage_kind,stored_bytes,reconstructed_bytes,payload_state FROM prompt_archive WHERE request_id=?`,id).Scan(&r.RequestID,&ms,&r.Model,&r.MessageCount,&r.ToolCount,&r.SystemBytes,&r.RawBytes,&r.Summary,&tr,&r.StorageKind,&r.StoredBytes,&r.ReconstructedBytes,&r.PayloadState);if err!=nil{return Record{},err};r.CreatedAt=fromMillis(ms);r.Truncated=tr!=0;r.Incremental=r.StorageKind=="delta";payload,err:=s.reconstructTx(ctx,tx,id);if err!=nil{r.PayloadState="unavailable";return r,nil};r.Payload=payload;return r,tx.Commit()}
func (s *Store) materializeDependentsTx(ctx context.Context,tx *sql.Tx,id string)error{rows,err:=tx.QueryContext(ctx,"SELECT request_id FROM prompt_archive WHERE base_request_id=?",id);if err!=nil{return err};var children []string;for rows.Next(){var child string;if err=rows.Scan(&child);err!=nil{rows.Close();return err};children=append(children,child)};if err=rows.Close();err!=nil{return err};for _,child:=range children{if err=s.materializeDependentsTx(ctx,tx,child);err!=nil{return err};payload,err:=s.reconstructTx(ctx,tx,child);if err!=nil{return err};if _,err=tx.ExecContext(ctx,"UPDATE prompt_archive SET storage_kind='full',base_request_id='',delta_depth=0,stored_bytes=? WHERE request_id=?",len(payload),child);err!=nil{return err};if _,err=tx.ExecContext(ctx,"UPDATE prompt_archive_payloads SET payload=? WHERE request_id=?",payload,child);err!=nil{return err}};return nil}
func (s *Store) Delete(ctx context.Context,id string)(bool,error){s.dbMu.Lock();defer s.dbMu.Unlock();return s.deleteLocked(ctx,id)}
func (s *Store) deleteLocked(ctx context.Context,id string)(bool,error){tx,err:=s.db.BeginTx(ctx,nil);if err!=nil{return false,err};ok:=false;defer func(){if !ok{_ = tx.Rollback()}}();if err=s.materializeDependentsTx(ctx,tx,id);err!=nil{return false,err};res,err:=tx.ExecContext(ctx,"DELETE FROM prompt_archive WHERE request_id=?",id);if err!=nil{return false,err};n,err:=res.RowsAffected();if err!=nil{return false,err};if err=tx.Commit();err!=nil{return false,err};ok=true;return n>0,nil}
func (s *Store) Statistics(ctx context.Context)(Statistics,error){var v Statistics;s.dbMu.Lock();defer s.dbMu.Unlock();err:=s.db.QueryRowContext(ctx,`SELECT COALESCE(SUM(CASE WHEN storage_kind='full' THEN 1 ELSE 0 END),0),COALESCE(SUM(CASE WHEN storage_kind='delta' THEN 1 ELSE 0 END),0),COALESCE(SUM(stored_bytes),0),COALESCE(SUM(reconstructed_bytes),0) FROM prompt_archive`).Scan(&v.FullCount,&v.DeltaCount,&v.StoredBytes,&v.ReconstructedBytes);return v,err}
func BuildRecord(requestID string,body []byte,req models.ClaudeRequest,now time.Time,sessionID ...string)Record{truncated:=len(body)>DefaultMaxPayloadBytes;payload:=body;if truncated{payload=[]byte(`{"archive":"payload unavailable: size limit exceeded"}`)}else if redacted,err:=diagnostics.RedactSecretsJSON(payload);err==nil{payload=redacted}else{payload=[]byte(`{"archive":"payload unavailable: invalid JSON"}`);truncated=true};r:=Record{RequestID:requestID,CreatedAt:now.UTC(),Model:req.Model,MessageCount:len(req.Messages),ToolCount:len(req.Tools),SystemBytes:jsonSize(req.System),RawBytes:len(body),Summary:summarizeRequest(req),Truncated:truncated,Payload:payload};if len(sessionID)>0{r.sessionID=sessionID[0]};return r}
func summarizeRequest(req models.ClaudeRequest)string{parts:=[]string{fmt.Sprintf("%d 条消息",len(req.Messages))};if len(req.Tools)>0{parts=append(parts,fmt.Sprintf("%d 个工具",len(req.Tools)))};if req.MaxTokens>0{parts=append(parts,fmt.Sprintf("max_tokens=%d",req.MaxTokens))};return strings.Join(parts," · ")}
func jsonSize(v any)int{if v==nil{return 0};b,_:=json.Marshal(v);return len(b)}
func buildWhere(q Query)(string,[]any){var c []string;var a []any;if q.RequestID!=""{c=append(c,"request_id=?");a=append(a,q.RequestID)};if q.Model!=""{c=append(c,"model=?");a=append(a,q.Model)};if q.Keyword!=""{c=append(c,"(request_id LIKE ? OR model LIKE ? OR summary LIKE ?)");v:="%"+q.Keyword+"%";a=append(a,v,v,v)};if !q.Since.IsZero(){c=append(c,"created_at>=?");a=append(a,toMillis(q.Since))};if !q.Until.IsZero(){c=append(c,"created_at<=?");a=append(a,toMillis(q.Until))};if len(c)==0{return "",a};return " WHERE "+strings.Join(c," AND "),a}
func boolInt(v bool)int{if v{return 1};return 0};func toMillis(v time.Time)int64{return v.UTC().UnixMilli()};func fromMillis(v int64)time.Time{return time.UnixMilli(v).UTC()}
